#!/usr/bin/env node
/**
 * `generate-read-scopes` — emit each vertical's `read-scopes.generated.ts`
 * from the curated source of truth.
 *
 * Those nine files carried an "AUTO-GENERATED … Do not edit by hand" banner
 * and no generator existed: nothing in `docs:all` or `scripts/` wrote them, and
 * `check-read-scopes.ts` only read them. They were maintained by hand, banner
 * notwithstanding.
 *
 * The tell was in the files themselves — nine files, SIX different wordings of
 * the same header comment. A generator emits one wording.
 *
 * That mattered beyond tidiness. A contributor who believes a file is
 * generated will not edit it, and one who edits it anyway cannot know whether
 * the next `docs:all` will silently revert the change. Both failure modes are
 * quiet.
 *
 * ## Why a JSON source rather than deriving from code
 *
 * These lists are not derivable. `READ_SCOPES` is a human judgement about
 * which of a platform's OAuth scopes are unambiguously read-only, checked
 * against that platform's published documentation — the reasoning and evidence
 * URL for each live in `scripts/read-scopes-audit.json`. Curation is the
 * input; this script is only the emitter.
 *
 * `curated-read-scopes.json` is keyed `<vertical>/<slug>` to match the audit
 * file, so the two read side by side.
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'

const REPO_ROOT = resolve(__dirname, '..')
const SOURCE = join(REPO_ROOT, 'scripts/curated-read-scopes.json')
const VERTICALS_DIR = join(REPO_ROOT, 'apps/integration-server/src/verticals')

interface Curated {
  readScopes?: string[]
  recommendedScopes?: string[]
}

/** One wording, emitted into every file — the drift this replaces. */
const HEADER = `// AUTO-GENERATED by scripts/generate-read-scopes.ts. Do not edit by hand.
// Source: scripts/curated-read-scopes.json — edit that, then run
//   pnpm run generate:read-scopes
// Maps platform slug → curated scopes for this vertical.
//   READ_SCOPES: unambiguously read-only OAuth scopes (subset of the catalog).
//   RECOMMENDED_SCOPES_EXTRA: the practical full scope catalog (read + write),
//     shown in the admin scope picker for platforms without a curated
//     read-only set.
// Curation rationale and per-platform evidence: scripts/read-scopes-audit.json
`

function renderMap(name: string, entries: Array<[string, string[]]>): string {
  const body = entries
    .map(([slug, scopes]) => {
      // A slug is a bare identifier only when it is a valid one; `monday-crm`
      // and the like must stay quoted or the emitted file will not parse.
      const key = /^[A-Za-z_$][\w$]*$/.test(slug) ? slug : `'${slug}'`
      // Short lists on one line, long ones expanded — matches how the
      // hand-maintained files read, and keeps a 100-scope catalogue reviewable.
      const oneLine = `  ${key}: [${scopes.map((s) => `'${s}'`).join(', ')}],`
      if (oneLine.length <= 100) return oneLine
      return `  ${key}: [\n${scopes.map((s) => `    '${s}',`).join('\n')}\n  ],`
    })
    .join('\n')
  return `export const ${name}: Record<string, readonly string[]> = {\n${body}\n}\n`
}

function main(): void {
  const curated = JSON.parse(readFileSync(SOURCE, 'utf8')) as Record<string, Curated>

  const byVertical = new Map<string, Array<[string, Curated]>>()
  for (const [key, entry] of Object.entries(curated)) {
    const slash = key.indexOf('/')
    if (slash < 0) throw new Error(`malformed key '${key}' — expected <vertical>/<slug>`)
    const vertical = key.slice(0, slash)
    const slug = key.slice(slash + 1)
    if (!byVertical.has(vertical)) byVertical.set(vertical, [])
    byVertical.get(vertical)!.push([slug, entry])
  }

  let written = 0
  for (const [vertical, entries] of [...byVertical].sort(([a], [b]) => a.localeCompare(b))) {
    // Sorted so a re-run never reorders, and a diff shows only real changes.
    const sorted = [...entries].sort(([a], [b]) => a.localeCompare(b))
    const read = sorted
      .filter(([, e]) => e.readScopes?.length)
      .map(([slug, e]) => [slug, e.readScopes!] as [string, string[]])
    const rec = sorted
      .filter(([, e]) => e.recommendedScopes?.length)
      .map(([slug, e]) => [slug, e.recommendedScopes!] as [string, string[]])

    const out = `${HEADER}\n${renderMap('READ_SCOPES', read)}\n${renderMap('RECOMMENDED_SCOPES_EXTRA', rec)}`
    writeFileSync(join(VERTICALS_DIR, vertical, 'platforms/read-scopes.generated.ts'), out)
    written++
  }

  console.log(
    `wrote ${written} read-scopes.generated.ts files from ${Object.keys(curated).length} curated platforms`,
  )
}

main()
